entries[1256301] = { ["name"] = "Voidfall", ["text"] = "Instant\nHavoc, Devourer\nConsume has a 35% chance to grant 1 stack of Voidfall.\n\nUpon reaching 3 stacks of Voidfall, Reap consumes a stack to reach into the Void and call down a meteor strike at your target's location, dealing (176% of Spell Power) Cosmic damage to all enemies within 8 yards. Damage reduced beyond 8 targets.\n\nVengeance\nFracture has a 35% chance to grant 1 stack of Voidfall.\n\nUpon reaching 3 stacks of Voidfall, Soul Cleave consumes a stack to reach into the Void and call down a meteor strike at your target's location, dealing (540% of Attack Power) Shadowflame damage to all enemies within 8 yards. Damage reduced beyond 8 targets." }
entries[1256302] = { ["name"] = "Voidfall", ["text"] = "Instant\nHavoc, Devourer\nConsume has a 35% chance to grant 1 stack of Voidfall.\n\nUpon reaching 3 stacks of Voidfall, Reap consumes a stack to reach into the Void and call down a meteor strike at your target's location, dealing (176% of Spell Power) Cosmic damage to all enemies within 8 yards. Damage reduced beyond 8 targets.\n\nVengeance\nFracture has a 35% chance to grant 1 stack of Voidfall.\n\nUpon reaching 3 stacks of Voidfall, Soul Cleave consumes a stack to reach into the Void and call down a meteor strike at your target's location, dealing (540% of Attack Power) Shadowflame damage to all enemies within 8 yards. Damage reduced beyond 8 targets.\n(700ms cooldown)" }
